{"file_path": "c:\Users\MI\Desktop\selfie_scorer\firmware\main\lcd.c", "content": "/* LCD 显示实现：esp_lcd(ST7789) + esp_lvgl_port(LVGL 8)。
 * 引脚/时序参数与 esp-bsp 的 esp32_s3_eye 板级定义保持一致：
 *   SPI3: SCLK=21 MOSI=47，DC=43 CS=44，无 RST；像素时钟 80MHz；
 *   颜色反相、RGB 顺序、240x240；背光 GPIO48 低电平点亮。
 * 背光用 GPIO 直拉（低有效）而非 LEDC PWM——避免与 esp32-camera 的
 * XCLK（LEDC_TIMER_0/CHANNEL_0）冲突。
 */
#include <stdio.h>
#include "esp_log.h"
#include "esp_check.h"
#include "driver/gpio.h"
#include "driver/spi_master.h"
#include "esp_lcd_panel_io.h"
#include "esp_lcd_panel_vendor.h"
#include "esp_lcd_panel_ops.h"
#include "esp_lvgl_port.h"
#include "lvgl.h"
#include "lcd.h"

static const char *TAG = "lcd";

/* ---- S3-EYE LCD 引脚（esp-bsp 官方定义） ---- */
#define LCD_SCLK        21
#define LCD_MOSI        47
#define LCD_DC          43
#define LCD_CS          44
#define LCD_BL          48
#define LCD_H_RES       240
#define LCD_V_RES       240
#define LCD_SPI_HOST    SPI3_HOST
#define LCD_PCLK_HZ     (80 * 1000 * 1000)
#define LCD_DRAW_ROWS   40            /* LVGL 绘制缓冲行数 */

/* 生成字库（lv_font_conv，黑体 16px，GB2312 一级 + 常用标点 + ASCII） */
extern const lv_font_t font_cn_16;

static lv_obj_t *lbl_status;
static lv_obj_t *lbl_total;
static lv_obj_t *lbl_dim;
static lv_obj_t *lbl_sugg;

static void ui_build(void)
{
    lv_obj_t *scr = lv_scr_act();
    lv_obj_set_style_bg_color(scr, lv_color_hex(0x101418), LV_PART_MAIN);

    /* 状态行 */
    lbl_status = lv_label_create(scr);
    lv_obj_set_style_text_font(lbl_status, &font_cn_16, 0);
    lv_obj_set_style_text_color(lbl_status, lv_color_hex(0x8ab4f8), 0);
    lv_label_set_text(lbl_status, "启动中…");
    lv_obj_align(lbl_status, LV_ALIGN_TOP_LEFT, 6, 4);

    /* 总分大字（数字用 Montserrat 48） */
    lbl_total = lv_label_create(scr);
    lv_obj_set_style_text_font(lbl_total, &lv_font_montserrat_48, 0);
    lv_obj_set_style_text_color(lbl_total, lv_color_hex(0xffffff), 0);
    lv_label_set_text(lbl_total, "--");
    lv_obj_align(lbl_total, LV_ALIGN_TOP_LEFT, 10, 26);

    /* 五维分数（中文小字，三行） */
    lbl_dim = lv_label_create(scr);
    lv_obj_set_style_text_font(lbl_dim, &font_cn_16, 0);
    lv_obj_set_style_text_color(lbl_dim, lv_color_hex(0xc8ccd0), 0);
    lv_label_set_text(lbl_dim, "");
    lv_obj_align(lbl_dim, LV_ALIGN_TOP_LEFT, 8, 88);

    /* 建议（自动换行，最多显示约 5 行） */
    lbl_sugg = lv_label_create(scr);
    lv_obj_set_style_text_font(lbl_sugg, &font_cn_16, 0);
    lv_obj_set_style_text_color(lbl_sugg, lv_color_hex(0xe8eaed), 0);
    lv_label_set_long_mode(lbl_sugg, LV_LABEL_LONG_WRAP);
    lv_obj_set_width(lbl_sugg, LCD_H_RES - 16);
    lv_label_set_text(lbl_sugg, "");
    lv_obj_align(lbl_sugg, LV_ALIGN_TOP_LEFT, 8, 142);
}

int lcd_init(void)
{
    /* 背光：GPIO 推挽输出，低电平点亮 */
    gpio_config_t bl = {
        .pin_bit_mask = 1ULL << LCD_BL,
        .mode = GPIO_MODE_OUTPUT,
    };
    gpio_config(&bl);
    gpio_set_level(LCD_BL, 1);            /* 先灭，初始化完成后再点亮 */

    /* SPI 总线 */
    spi_bus_config_t buscfg = {
        .sclk_io_num = LCD_SCLK,
        .mosi_io_num = LCD_MOSI,
        .miso_io_num = GPIO_NUM_NC,
        .quadwp_io_num = GPIO_NUM_NC,
        .quadhd_io_num = GPIO_NUM_NC,
        .max_transfer_sz = LCD_H_RES * LCD_DRAW_ROWS * sizeof(uint16_t),
    };
    ESP_RETURN_ON_ERROR(spi_bus_initialize(LCD_SPI_HOST, &buscfg, SPI_DMA_CH_AUTO),
                        TAG, "SPI bus init failed");

    /* panel IO（带 DC/CS 的 SPI 液晶时序） */
    esp_lcd_panel_io_handle_t io = NULL;
    esp_lcd_panel_io_spi_config_t io_config = {
        .dc_gpio_num = LCD_DC,
        .cs_gpio_num = LCD_CS,
        .pclk_hz = LCD_PCLK_HZ,
        .lcd_cmd_bits = 8,
        .lcd_param_bits = 8,
        .spi_mode = 0,
        .trans_queue_depth = 10,
    };
    ESP_RETURN_ON_ERROR(esp_lcd_new_panel_io_spi((esp_lcd_spi_bus_handle_t)LCD_SPI_HOST,
                                                  &io_config, &io),
                        TAG, "panel io failed");

    /* ST7789 面板 */
    esp_lcd_panel_handle_t panel = NULL;
    esp_lcd_panel_dev_config_t panel_config = {
        .reset_gpio_num = GPIO_NUM_NC,
        .flags.reset_active_high = 0,
        .rgb_ele_order = LCD_RGB_ELEMENT_ORDER_RGB,
        .bits_per_pixel = 16,
    };
    ESP_RETURN_ON_ERROR(esp_lcd_new_panel_st7789(io, &panel_config, &panel),
                        TAG, "st7789 panel failed");
    ESP_RETURN_ON_ERROR(esp_lcd_panel_reset(panel), TAG, "panel reset failed");
    ESP_RETURN_ON_ERROR(esp_lcd_panel_init(panel), TAG, "panel init failed");
    esp_lcd_panel_invert_color(panel, true);
    esp_lcd_panel_swap_xy(panel, false);
    esp_lcd_panel_mirror(panel, false, false);

    /* LVGL（esp_lvgl_port 起 LVGL 任务，绘制缓冲 DMA 内存） */
    const lvgl_port_cfg_t lvgl_cfg = ESP_LVGL_PORT_INIT_CONFIG();
    ESP_RETURN_ON_ERROR(lvgl_port_init(&lvgl_cfg), TAG, "lvgl port init failed");
    lvgl_port_display_cfg_t disp_cfg = {
        .io_handle = io,
        .panel_handle = panel,
        .buffer_size = LCD_H_RES * LCD_DRAW_ROWS,
        .double_buffer = true,
        .hres = LCD_H_RES,
        .vres = LCD_V_RES,
        .monochrome = false,
        .rotation = {
            .swap_xy = false,
            .mirror_x = false,
            .mirror_y = false,
        },
        .flags = {
            .buff_dma = true,
            .buff_spiram = false,
            .sw_rotate = false,
            .swap_bytes = true,     /* S3-EYE 屏为大端序（BSP_LCD_BIGENDIAN=1） */
        },
    };
    if (!lvgl_port_add_disp(&disp_cfg)) {
        ESP_LOGE(TAG, "lvgl add display failed");
        return -1;
    }

    esp_lcd_panel_disp_on_off(panel, true);
    gpio_set_level(LCD_BL, 0);            /* 点亮背光（低有效） */

    lvgl_port_lock(0);
    ui_build();
    lvgl_port_unlock();
    ESP_LOGI(TAG, "LCD 240x240 + LVGL 就绪");
    return 0;
}

void lcd_status(const char *text)
{
    if (!lbl_status) {
        return;
    }
    if (lvgl_port_lock(100)) {
        lv_label_set_text(lbl_status, text);
        lvgl_port_unlock();
    }
}

void lcd_show_result(const score_result_t *r)
{
    if (!lbl_total) {
        return;
    }
    if (!lvgl_port_lock(100)) {
        return;
    }
    lv_label_set_text_fmt(lbl_total, "%.1f", r->total);
    lv_label_set_text_fmt(lbl_dim,
        "颜值 %.1f   美学 %.1f\n曝光 %.2f  人脸 %.2f\n构图 %.1f   %s",
        r->beauty, r->aesthetic, r->exposure, r->face_quality,
        r->composition, r->grade);
    lv_label_set_text(lbl_sugg,
        r->first_suggestion[0] ? r->first_suggestion : "（无建议）");
    lvgl_port_unlock();
}
"}

